65	// appendSubmitEvent 以给定序号追加提交履历：内容即该次提交的维修结果，
66	// 履历的全库序号即提交身份。
67	func (s *store) appendSubmitEvent(seq int, t *Ticket, result string) {
68		s.data.Events = append(s.data.Events, Event{
69			Seq:      seq,
70			AssetID:  t.AssetID,
71			TicketID: t.ID,
