91	}
92	
93	// submitRepair 提交未关闭工单的维修结果：工单转为待验收，追加一条提交履历并
94	// 返回其全库序号作为提交身份。失败路径不修改任何业务数据，也不消耗履历序号。
95	func (s *store) submitRepair(ticketID, result string) (*Ticket, int, error) {
96		t := s.findTicket(ticketID)
97		if t == nil {
98			return nil, 0, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
99		}
100		switch t.Status {
