128		TargetSeq    int       `json:"-"`
129		Decision     string    `json:"-"`
130		NewContent   string    `json:"-"`
131		OldContent   string    `json:"-"`
132		OldDue       string    `json:"-"`
133		OldInterval  int       `json:"-"`
134		OldNextDue   string    `json:"-"`
135		PartID       string    `json:"-"`
136		Quantity     int       `json:"-"`
137		WithdrawalID string    `json:"-"`
138		AttachmentID string    `json:"-"`
139		Path         string    `json:"-"`
140		Time         time.Time `json:"-"`
141	}
