143	// eventJSON 与 Event 对应，时间以 RFC3339 文本持久化。
144	type eventJSON struct {
145		Seq          int    `json:"seq"`
146		AssetID      string `json:"asset_id"`
147		TicketID     string `json:"ticket_id,omitempty"`
148		Kind         string `json:"kind"`
149		Content      string `json:"content"`
150		From         string `json:"from,omitempty"`
