170	func (e Event) toJSON() eventJSON {
171		return eventJSON{
172			Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
173			Kind: e.Kind, Content: e.Content, From: e.From, To: e.To,
174			Due: e.Due, Done: e.Done, Interval: e.Interval, TargetSeq: e.TargetSeq,
175			Decision:   e.Decision,
176			NewContent: e.NewContent, OldContent: e.OldContent,
177			OldDue: e.OldDue, OldInterval: e.OldInterval, OldNextDue: e.OldNextDue,
178			PartID: e.PartID, Quantity: e.Quantity, WithdrawalID: e.WithdrawalID,
179			AttachmentID: e.AttachmentID, Path: e.Path,
180			// RFC3339Nano 保留小数秒精度；整秒时输出与 RFC3339 完全一致，
181			// 因此既有整秒台账的字节表示不变，而旧库中带小数秒的履历时间
182			// 在重新保存（含导入合并后的提交）时也不会被截断。
183			Time: e.Time.Format(time.RFC3339Nano),
184		}
185	}
