1274	// maintValidateError 把保养规则核心返回的规则冲突包装为台账校验场景的错误
1275	// （指明“履历矛盾”类别）；调用方拒绝查询与写入并保留原文件。
1276	func maintValidateError(err error) error {
1277		var re *maintRuleError
1278		if !errors.As(err, &re) {
1279			return err
1280		}
1281		switch re.code {
1282		case ruleDuplicateCreate:
1283			return fmt.Errorf("履历矛盾：资产 %s 有多条保养建立履历", re.assetID)
1284		case ruleBeforeCreate:
1285			return fmt.Errorf("履历矛盾：资产 %s 的%s履历（序号 %d）出现在建立履历之前",
1286				re.assetID, re.kind, re.seq)
1287		case ruleAdjustScheme:
1288			return fmt.Errorf("履历矛盾：保养调整履历（序号 %d）记录的原方案与资产 %s 当时的方案不符",
1289				re.seq, re.assetID)
1290		case ruleAdjustNextDue:
1291			return fmt.Errorf("履历矛盾：保养调整履历（序号 %d）记录的原下一到期日 %s 与当时的下一到期日 %s 不符",
1292				re.seq, re.dateA, re.dateB)
1293		case ruleAdjustFirstDue:
1294			return fmt.Errorf("履历矛盾：保养调整履历（序号 %d）的新首次到期日 %s 未严格晚于未撤销完成（序号 %d）的实际完成日 %s",
1295				re.seq, re.dateA, re.doneSeq, re.dateB)
1296		case ruleRevokeOldSegment:
1297			return fmt.Errorf("履历矛盾：保养撤销履历（序号 %d）的目标序号 %d 属于资产 %s 调整前的旧方案段，旧段完成不能再撤销",
1298				re.seq, re.target, re.assetID)
1299		case ruleRevokeUnknown:
1300			return fmt.Errorf("履历矛盾：保养撤销履历（序号 %d）的目标序号 %d 不是资产 %s 先前的完成履历",
1301				re.seq, re.target, re.assetID)
1302		case ruleRevokeDuplicate:
1303			return fmt.Errorf("履历矛盾：完成履历序号 %d 被重复撤销（撤销履历序号 %d）", re.target, re.seq)
1304		case ruleRevokeNotLatest:
1305			return fmt.Errorf("履历矛盾：保养撤销履历（序号 %d）的目标序号 %d 不是当时最新的有效完成（序号 %d）",
1306				re.seq, re.target, re.latest)
1307		case ruleDoneDeactivated:
1308			return fmt.Errorf("履历矛盾：资产 %s 在停用期间出现保养完成履历（序号 %d）", re.assetID, re.seq)
1309		case ruleDueMismatch:
1310			return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）周期到期日 %s 与当前下一到期日 %s 不接续",
1311				re.assetID, re.seq, re.dateA, re.dateB)
1312		case ruleDoneBeforeDue:
1313			return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）完成日 %s 早于周期到期日 %s",
1314				re.assetID, re.seq, re.dateA, re.dateB)
1315		case ruleNextOverflow:
1316			return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）无法推出日期范围内的下一到期日",
1317				re.assetID, re.seq)
1318		}
1319		return err
1320	}
