1322	// save 将全部业务数据一次性原子写入：先写同目录临时文件，fsync 后 rename
1323	// 覆盖正式文件。写入前先校验待提交数据的一致性；校验或读写失败时原文件
1324	// 保持不变，不留下部分业务变化。
1325	func (s *store) save() error {
1326		s.data.EventsJSON = make([]eventJSON, len(s.data.Events))
1327		for i, e := range s.data.Events {
1328			s.data.EventsJSON[i] = e.toJSON()
1329		}
1330		if err := validateData(s.data); err != nil {
1331			return fmt.Errorf("待保存数据未通过一致性检查：%w（未写入任何数据）", err)
1332		}
1333		var buf bytes.Buffer
1334		enc := json.NewEncoder(&buf)
1335		enc.SetIndent("", "  ")
1336		if err := enc.Encode(s.data); err != nil {
1337			return fmt.Errorf("编码数据失败: %w", err)
1338		}
1339		if err := os.MkdirAll(s.dir, 0o755); err != nil {
1340			return fmt.Errorf("创建数据目录失败: %w", err)
1341		}
1342		path := filepath.Join(s.dir, dataFileName)
1343		tmp, err := os.CreateTemp(s.dir, ".caretrack-*.tmp")
1344		if err != nil {
1345			return fmt.Errorf("创建临时数据文件失败: %w", err)
1346		}
1347		tmpName := tmp.Name()
1348		abort := func(err error) error {
1349			_ = tmp.Close()
1350			_ = os.Remove(tmpName)
1351			return err
1352		}
1353		if _, err := tmp.Write(buf.Bytes()); err != nil {
1354			abort(nil)
1355			return fmt.Errorf("写入数据失败: %w", err)
1356		}
1357		if err := tmp.Sync(); err != nil {
1358			abort(nil)
1359			return fmt.Errorf("写入数据失败: %w", err)
1360		}
1361		if err := tmp.Close(); err != nil {
1362			_ = os.Remove(tmpName)
1363			return fmt.Errorf("写入数据失败: %w", err)
1364		}
1365		if err := os.Rename(tmpName, path); err != nil {
1366			_ = os.Remove(tmpName)
1367			return fmt.Errorf("保存数据失败: %w", err)
1368		}
1369		return nil
1370	}
1371	
1372	func (s *store) findAsset(id string) *Asset {
1373		for _, a := range s.data.Assets {
1374			if a.ID == id {
1375				return a
1376			}
1377		}
1378		return nil
1379	}
1380	
1381	func (s *store) findTicket(id string) *Ticket {
1382		for _, t := range s.data.Tickets {
1383			if t.ID == id {
1384				return t
1385			}
1386		}
1387		return nil
1388	}
1389	
1390	func (s *store) findRequest(requestID string) *requestBinding {
1391		for i := range s.data.Requests {
1392			if s.data.Requests[i].RequestID == requestID {
1393				return &s.data.Requests[i]
1394			}
1395		}
1396		return nil
1397	}
1398	
1399	// openTicketOf 返回资产当前未终结（未关闭或待验收）的工单；待验收工单仍占用
1400	// 资产，因此报修、停用、恢复使用与详情展示都把待验收视为未终结。
1401	func (s *store) openTicketOf(assetID string) *Ticket {
1402		for _, t := range s.data.Tickets {
1403			if t.AssetID == assetID && (t.Status == ticketOpen || t.Status == ticketPending) {
1404				return t
1405			}
1406		}
1407		return nil
1408	}
1409	
1410	func (s *store) eventsOf(assetID string) []Event {
1411		out := make([]Event, 0)
1412		for _, e := range s.data.Events {
1413			if e.AssetID == assetID {
1414				out = append(out, e)
1415			}
1416		}
1417		sort.SliceStable(out, func(i, j int) bool { return out[i].Seq < out[j].Seq })
1418		return out
1419	}
1420	
1421	// nextEventSeq 返回下一条履历应使用的全库唯一正整数序号；计数器耗尽时报错。
1422	func (s *store) nextEventSeq() (int, error) {
1423		maxSeq := 0
1424		for _, e := range s.data.Events {
1425			if e.Seq > maxSeq {
1426				maxSeq = e.Seq
1427			}
1428		}
1429		if maxSeq == math.MaxInt {
1430			return 0, fmt.Errorf("%w: 履历序号计数器已耗尽，无法追加履历", errConflict)
1431		}
1432		return maxSeq + 1, nil
1433	}
1434	
1435	// appendEvent 以给定序号追加履历。调用方须先通过 nextEventSeq 取得序号，
1436	// 确保任何失败路径都不会在部分变更后才报错。from/to 仅派工履历使用。
1437	func (s *store) appendEvent(seq int, assetID, ticketID, kind, content, from, to string) {
1438		s.data.Events = append(s.data.Events, Event{
1439			Seq:      seq,
1440			AssetID:  assetID,
1441			TicketID: ticketID,
1442			Kind:     kind,
1443			Content:  content,
1444			From:     from,
1445			To:       to,
1446			Time:     s.now(),
1447		})
1448	}
1449	
1450	func (s *store) registerAsset(id, name, location string) (*Asset, error) {
1451		if s.findAsset(id) != nil {
1452			return nil, fmt.Errorf("%w: 资产编号 %q 已存在", errConflict, id)
1453		}
1454		a := &Asset{ID: id, Name: name, Location: location, Status: statusAvailable}
1455		s.data.Assets = append(s.data.Assets, a)
1456		return a, nil
1457	}
1458	
1459	// report 创建报修工单。返回 (工单, 是否为去重重放, 错误)。
1460	// 所有失败路径都不修改任何业务数据，也不会绑定新的请求标识。
1461	func (s *store) report(assetID, description, requestID string) (*Ticket, bool, error) {
1462		// 已有绑定：相同资产+描述 => 返回原工单（无论其是否已关闭、是否已有新工单）；
1463		// 资产或描述不同 => 拒绝。
1464		if r := s.findRequest(requestID); r != nil {
1465			if r.AssetID != assetID || r.Description != description {
1466				return nil, false, fmt.Errorf(
1467					"%w: 请求标识 %q 已用于资产 %q 的另一笔报修，不能搭配不同的资产编号或故障描述",
1468					errConflict, requestID, r.AssetID)
1469			}
1470			t := s.findTicket(r.TicketID)
1471			if t == nil {
1472				return nil, false, fmt.Errorf("数据内部错误：请求标识 %q 绑定的工单不存在", requestID)
1473			}
1474			return t, true, nil
1475		}
1476	
1477		asset := s.findAsset(assetID)
1478		if asset == nil {
1479			return nil, false, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
1480		}
1481		if asset.Status == statusDeactivated {
1482			// 停用期间拒绝新报修，也不绑定新请求标识；恢复使用后可用同一标识重试。
1483			return nil, false, fmt.Errorf("%w: 资产 %s 已停用，不能报修", errConflict, assetID)
1484		}
1485		if t := s.openTicketOf(assetID); t != nil {
1486			return nil, false, fmt.Errorf("%w: 资产 %s 已有未关闭工单 %s", errConflict, assetID, t.ID)
1487		}
1488		// 先确认编号与履历计数器都能推进，再修改任何业务数据：
1489		// 编号耗尽时拒绝新报修，不消耗编号，也不绑定请求标识。
1490		seq := s.data.NextTicketSeq
1491		if seq < 1 || seq == math.MaxInt {
1492			return nil, false, fmt.Errorf("%w: 工单编号计数器已耗尽，无法分配新工单编号", errConflict)
1493		}
1494		eventSeq, err := s.nextEventSeq()
1495		if err != nil {
1496			return nil, false, err
1497		}
1498		t := &Ticket{
1499			ID:          fmt.Sprintf("T%04d", seq),
1500			AssetID:     assetID,
1501			Description: description,
1502			RequestID:   requestID,
1503			Status:      ticketOpen,
1504			CreatedAt:   s.now().Format(time.RFC3339),
1505			// 报修地点在报修时按当时资产位置确定；之后位置变更不改写本字段，
1506			// 由加载/保存校验保证它与按报修履历序号追溯的位置一致。
1507			ReportLocation: asset.Location,
1508		}
1509		s.data.NextTicketSeq = seq + 1
1510		s.data.Tickets = append(s.data.Tickets, t)
1511		s.data.Requests = append(s.data.Requests, requestBinding{
1512			RequestID:   requestID,
1513			AssetID:     assetID,
1514			Description: description,
1515			TicketID:    t.ID,
1516		})
1517		asset.Status = statusRepairing
1518		s.appendEvent(eventSeq, assetID, t.ID, eventReport, description, "", "")
1519		return t, false, nil
1520	}
1521	
1522	// closeTicket 关闭未关闭工单并把资产恢复为可用。仅从未提交的工单可直接关闭；
1523	// 首次提交后只能验收通过或取消终结（退回后也不能绕过验收直接关闭）。
1524	// 失败路径不修改任何业务数据。
1525	func (s *store) closeTicket(ticketID, result string) (*Ticket, *Asset, error) {
1526		t := s.findTicket(ticketID)
1527		if t == nil {
1528			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1529		}
1530		if t.Status == ticketCancelled {
1531			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能关闭", errConflict, ticketID)
1532		}
1533		if t.Status == ticketPending {
1534			return nil, nil, fmt.Errorf("%w: 工单 %s 处于待验收，须验收通过或取消终结，不能直接关闭", errConflict, ticketID)
1535		}
1536		if t.Status != ticketOpen {
1537			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能重复关闭", errConflict, ticketID)
1538		}
1539		if s.hasSubmission(ticketID) {
1540			return nil, nil, fmt.Errorf("%w: 工单 %s 已提交过维修，不能直接关闭，须重新提交并验收通过或取消", errConflict, ticketID)
1541		}
1542		asset := s.findAsset(t.AssetID)
1543		if asset == nil {
1544			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
1545		}
1546		eventSeq, err := s.nextEventSeq()
1547		if err != nil {
1548			return nil, nil, err
1549		}
1550		t.Status = ticketClosed
1551		t.Result = result
1552		t.ClosedAt = s.now().Format(time.RFC3339)
1553		asset.Status = statusAvailable
1554		s.appendEvent(eventSeq, asset.ID, t.ID, eventClose, result, "", "")
1555		return t, asset, nil
1556	}
1557	
1558	// cancelTicket 取消未关闭或待验收工单并把资产恢复为可用。取消是终态，但不代表
1559	// 维修完成：不填写维修结果，不删除工单、履历（含全部提交与验收履历）或请求
1560	// 绑定，工单编号不回退也不复用。失败路径不修改任何业务数据。
1561	func (s *store) cancelTicket(ticketID, reason string) (*Ticket, *Asset, error) {
1562		t := s.findTicket(ticketID)
1563		if t == nil {
1564			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1565		}
1566		if t.Status == ticketCancelled {
1567			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能再次取消", errConflict, ticketID)
1568		}
1569		if t.Status == ticketClosed {
1570			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能取消", errConflict, ticketID)
1571		}
1572		asset := s.findAsset(t.AssetID)
1573		if asset == nil {
1574			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
1575		}
1576		eventSeq, err := s.nextEventSeq()
1577		if err != nil {
1578			return nil, nil, err
1579		}
1580		t.Status = ticketCancelled
1581		t.CancelReason = reason
1582		t.CancelledAt = s.now().Format(time.RFC3339)
1583		asset.Status = statusAvailable
1584		s.appendEvent(eventSeq, asset.ID, t.ID, eventCancel, reason, "", "")
1585		return t, asset, nil
1586	}
1587	
1588	// assignTicket 为未关闭工单派工或转派：没有负责人时首次派工，已有负责人时
1589	// 转派给不同人员。人员标识只是本地文本记录，不对应任何人员账户。
1590	// 成功后保存负责人、变更时间与说明，并追加一条含原负责人（首次派工为空，
1591	// 展示为“未派工”）、新负责人及说明的派工履历。派工不创建工单、不消耗工单
1592	// 编号，也不改变资产状态或报修请求绑定。失败路径不修改任何业务数据。
1593	func (s *store) assignTicket(ticketID, assignee, note string) (*Ticket, error) {
1594		t := s.findTicket(ticketID)
1595		if t == nil {
1596			return nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1597		}
1598		if t.Status == ticketClosed {
1599			return nil, fmt.Errorf("%w: 工单 %s 已关闭，不能派工", errConflict, ticketID)
1600		}
1601		if t.Status == ticketCancelled {
1602			return nil, fmt.Errorf("%w: 工单 %s 已取消，不能派工", errConflict, ticketID)
1603		}
1604		if t.Status == ticketPending {
1605			return nil, fmt.Errorf("%w: 工单 %s 处于待验收，不能派工", errConflict, ticketID)
1606		}
1607		if assignee == "" {
1608			return nil, fmt.Errorf("%w: 维修人员标识不能为空", errConflict)
1609		}
1610		if note == "" {
1611			return nil, fmt.Errorf("%w: 派工说明不能为空", errConflict)
1612		}
1613		if t.Assignee == assignee {
1614			return nil, fmt.Errorf("%w: 工单 %s 当前负责人已是 %s，不能重复派给同一人",
1615				errConflict, ticketID, assignee)
1616		}
1617		eventSeq, err := s.nextEventSeq()
1618		if err != nil {
1619			return nil, err
1620		}
1621		s.appendEvent(eventSeq, t.AssetID, t.ID, eventAssign, note, t.Assignee, assignee)
1622		t.Assignee = assignee
1623		t.AssignedAt = s.now().Format(time.RFC3339)
1624		t.AssignNote = note
1625		return t, nil
1626	}
1627

