1	package main
2	
3	import (
4		"errors"
5		"fmt"
6		"io"
7		"math"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12	)
13	
14	// 资产批量导入：把源数据目录中所选资产连同其全部工单、报修请求绑定、
15	// 报修/派工/关闭/取消履历、停用/恢复使用履历（含当前停用或可用状态）、
16	// 位置起点（最早一条位置变更履历的原位置；没有位置履历则为资产保存位置）、
17	// 当前位置与全部位置变更履历、备件领用记录、附件索引（含登记/撤销履历）
18	// 与保养计划（含保养建立/完成/撤销/调整履历）复制到目标数据目录。
19	//
20	// 关键规则：
21	//   - 导入是复制：源台账始终只读，不删除、不修改任何源记录；同一台账不能导入自身。
22	//   - 工单编号按源工单序号升序，从目标的下一工单序号重新分配，并同步替换履历与
23	//     请求绑定中的工单引用；目标原有记录不改编号、不改变业务含义。
24	//   - 备件领用编号按源领用履历的全库序号整体排序（编号大小不代表领用先后），
25	//     从目标的下一领用序号重新分配并输出映射；领用记录的工单引用与退回履历中的
26	//     领用引用同步替换，数量、累计退回与净量保持。导入的未关闭工单可继续退回。
27	//   - 附件编号按源登记履历的全库序号整体排序，从目标的下一附件序号重新分配并
28	//     输出映射；附件记录的工单引用与登记、撤销履历中的附件引用同步替换，路径、
29	//     撤销状态、说明与理由保持。只复制索引，不复制资料文件；文件当前不可用不使
30	//     导入失败。
31	//   - 履历按源履历序号排列，在目标已有最大履历序号之后依次分配新序号，保留原操作
32	//     顺序（不按时间重排）；履历时间保留原瞬间与小数秒精度。导入本身不追加报修
33	//     或其他业务事件。提交与验收履历随工单一并复制，验收履历中的目标提交序号随
34	//     履历重编号同步替换，并输出提交履历序号的原、新映射；导入后可用目标序号
35	//     继续验收当前待验收提交。
36	//   - 保养计划随资产原样复制（内容、首次到期日、间隔与下一到期日不变），保养履历
37	//     （含撤销与调整履历）随资产履历一并复制，完成与撤销链自然接续，方案段边界、
38	//     顺序与时间精度保持，撤销履历中的目标
39	//     完成序号随履历重编号同步替换，并输出完成履历序号的原、新映射；目标已有计划
40	//     不受影响。导入后可用新完成序号继续撤销，也可继续调整方案。
41	//   - 停用、恢复使用为资产级履历，随资产履历一并复制并重编号，资产当前的停用或
42	//     可用状态原样保留；导入后可继续恢复使用或停用。
43	//   - 位置起点、当前位置与全部位置变更履历随资产一并复制并沿用履历重编号，保留
44	//     原位置、新位置、理由的先后关系与时间精度；导入本身不新增搬移事件。工单
45	//     复制时保留其报修地点（即源台账报修履历序号当时的资产位置），导入后的
46	//     工单报修地点保持不变，资产可在目标库继续变更位置。
47	//   - 资产编号在目标已存在，或所选工单的任一请求标识已在目标绑定时，整批拒绝：
48	//     不覆盖、不合并、不改请求标识。
49	//   - 操作前检查源、目标整库一致性，提交前由 save 再检查合并后的数据；整批变化
50	//     一次原子写入目标。任何失败都不改动两边原文件、不留下部分导入、不消耗目标编号。
51	
52	// stringListFlag 收集可重复的 --asset-id 参数。
53	type stringListFlag []string
54	
55	func (f *stringListFlag) String() string { return strings.Join(*f, ",") }
56	
57	func (f *stringListFlag) Set(v string) error {
58		*f = append(*f, v)
59		return nil
60	}
61	
62	// ticketRemap 记录一张工单的原编号与新编号。
63	type ticketRemap struct {
64		OldID string
65		NewID string
66	}
67	
68	// partRemap 记录一笔备件领用的原领用编号与新领用编号。
69	type partRemap struct {
70		OldID string
71		NewID string
72	}
73	
74	// attachRemap 记录一条附件索引的原附件编号与新附件编号。
75	type attachRemap struct {
76		OldID string
77		NewID string
78	}
79	
80	// completionRemap 记录一条保养完成履历的原全库序号与新全库序号。
81	type completionRemap struct {
82		OldSeq int
83		NewSeq int
84	}
85	
86	// importOutcome 为一次成功导入的结果摘要，用于输出。
87	type importOutcome struct {
88		assetIDs    []string
89		tickets     []ticketRemap
90		parts       []partRemap
91		attachments []attachRemap
92		completions []completionRemap
93		submissions []completionRemap
94		plans       int
95	}
96	
97	func cmdImport(args []string, w io.Writer) error {
98		var opts cmdOptions
99		var sourceDir string
100		var assetIDs stringListFlag
101		fs := newFlagSet("import", &opts)
102		fs.StringVar(&sourceDir, "source-dir", "", "源数据目录（必填，只读，不会被修改）")
103		fs.Var(&assetIDs, "asset-id", "要导入的资产编号（必填，可重复；重复编号按一项处理）")
104		if err := parseFlags(fs, args); err != nil {
105			return err
106		}
107		if err := requireFlag(fs, sourceDir, "source-dir"); err != nil {
108			return err
109		}
110		if len(assetIDs) == 0 {
111			return &usageError{msg: "命令 import 缺少必填参数 --asset-id（至少一项资产编号）"}
112		}
113		for _, id := range assetIDs {
114			if id == "" {
115				return &usageError{msg: "命令 import 的 --asset-id 不能为空"}
116			}
117		}
118	
119		outcome, err := importAssets(opts.dataDir, sourceDir, []string(assetIDs))
120		if err != nil {
121			return err
122		}
123		fmt.Fprintf(w, "已导入 %d 项资产（%s）。\n", len(outcome.assetIDs), strings.Join(outcome.assetIDs, ", "))
124		if outcome.plans > 0 {
125			fmt.Fprintf(w, "同时导入 %d 项保养计划及其保养履历。\n", outcome.plans)
126		}
127		if len(outcome.tickets) == 0 {
128			fmt.Fprintln(w, "所选资产没有工单，未分配新工单编号。")
129		} else {
130			fmt.Fprintln(w, "工单编号映射（原编号 -> 新编号）:")
131			for _, m := range outcome.tickets {
132				fmt.Fprintf(w, "%s -> %s\n", m.OldID, m.NewID)
133			}
134		}
135		if len(outcome.parts) > 0 {
136			fmt.Fprintln(w, "领用编号映射（原编号 -> 新编号）:")
137			for _, m := range outcome.parts {
138				fmt.Fprintf(w, "%s -> %s\n", m.OldID, m.NewID)
139			}
140		}
141		if len(outcome.attachments) > 0 {
142			fmt.Fprintln(w, "附件编号映射（原编号 -> 新编号）:")
143			for _, m := range outcome.attachments {
144				fmt.Fprintf(w, "%s -> %s\n", m.OldID, m.NewID)
145			}
146		}
147		if len(outcome.completions) > 0 {
148			fmt.Fprintln(w, "完成履历序号映射（原序号 -> 新序号）:")
149			for _, m := range outcome.completions {
150				fmt.Fprintf(w, "%d -> %d\n", m.OldSeq, m.NewSeq)
151			}
152		}
153		if len(outcome.submissions) > 0 {
154			fmt.Fprintln(w, "提交履历序号映射（原序号 -> 新序号）:")
155			for _, m := range outcome.submissions {
156				fmt.Fprintf(w, "%d -> %d\n", m.OldSeq, m.NewSeq)
157			}
158		}
159		return nil
160	}
161	
162	// importAssets 把 sourceDir 中编号为 assetIDs 的资产导入 targetDir。
163	// 源目录只读；目标目录无台账时在成功导入时创建。任何一步失败都整批失败，
164	// 两边原文件字节保持不变。
165	func importAssets(targetDir, sourceDir string, assetIDs []string) (*importOutcome, error) {
166		srcAbs, err := filepath.Abs(sourceDir)
167		if err != nil {
168			return nil, fmt.Errorf("无法解析源数据目录: %w", err)
169		}
170		dstAbs, err := filepath.Abs(targetDir)
171		if err != nil {
172			return nil, fmt.Errorf("无法解析目标数据目录: %w", err)
173		}
174		if srcAbs == dstAbs {
175			return nil, errors.New("源数据目录与目标数据目录相同：同一台账不能导入自身")
176		}
177		// 路径不同也可能指向同一台账文件（符号链接等），按文件再判一次。
178		srcPath := filepath.Join(srcAbs, dataFileName)
179		dstPath := filepath.Join(dstAbs, dataFileName)
180		if fi1, err1 := os.Stat(srcPath); err1 == nil {
181			if fi2, err2 := os.Stat(dstPath); err2 == nil && os.SameFile(fi1, fi2) {
182				return nil, errors.New("源与目标指向同一台账文件：同一台账不能导入自身")
183			}
184		}
185	
186		// 源台账必须已存在并通过整库一致性检查；源始终只读，绝不写入。
187		src, err := openSourceStore(srcAbs)
188		if err != nil {
189			return nil, err
190		}
191		// 目标：无台账时视为空库（成功导入时创建）；已有台账同样先做整库一致性检查。
192		dst, err := openStore(dstAbs)
193		if err != nil {
194			return nil, err
195		}
196		outcome, err := dst.mergeImport(src, assetIDs)
197		if err != nil {
198			return nil, err
199		}
200		// save 先校验合并后的整库一致性，再一次性原子写入；失败时目标原文件不变。
201		if err := dst.save(); err != nil {
202			return nil, err
203		}
204		return outcome, nil
205	}
206	
207	// mergeImport 在内存中把源台账的所选资产合并进目标数据：先做全部冲突与容量
208	// 检查，再一次性应用，任何失败都不会留下部分变更。调用方负责随后的原子保存。
209	func (s *store) mergeImport(src *store, assetIDs []string) (*importOutcome, error) {
210		// 重复编号按一项处理，保持首次出现的顺序。
211		selected := map[string]bool{}
212		ids := make([]string, 0, len(assetIDs))
213		for _, id := range assetIDs {
214			if !selected[id] {
215				selected[id] = true
216				ids = append(ids, id)
217			}
218		}
219		// 所选资产必须存在于源，且编号在目标中不存在。
220		assets := make([]*Asset, 0, len(ids))
221		for _, id := range ids {
222			a := src.findAsset(id)
223			if a == nil {
224				return nil, fmt.Errorf("%w: 源台账中不存在资产编号 %q", errNotFound, id)
225			}
226			if s.findAsset(id) != nil {
227				return nil, fmt.Errorf("%w: 资产编号 %q 在目标台账中已存在，整批拒绝导入", errConflict, id)
228			}
229			assets = append(assets, a)
230		}
231		// 所选资产的全部工单，按源工单序号升序重新分配编号。
232		tickets := make([]*Ticket, 0)
233		for _, t := range src.data.Tickets {
234			if selected[t.AssetID] {
235				tickets = append(tickets, t)
236			}
237		}
238		sort.SliceStable(tickets, func(i, j int) bool {
239			ni, _ := parseTicketSeq(tickets[i].ID)
240			nj, _ := parseTicketSeq(tickets[j].ID)
241			return ni < nj
242		})
243		// 工单编号容量：与 report 同一约束，可分配的最大序号为 math.MaxInt-1。
244		if len(tickets) > math.MaxInt-s.data.NextTicketSeq {
245			return nil, fmt.Errorf(
246				"%w: 目标工单编号容量不足：下一序号 %d 无法容纳 %d 张导入工单，整批拒绝导入",
247				errConflict, s.data.NextTicketSeq, len(tickets))
248		}
249		// 所选工单的任一请求标识已在目标绑定时整批拒绝，不改请求标识。
250		srcReqByTicket := map[string]*requestBinding{}
251		for i := range src.data.Requests {
252			r := &src.data.Requests[i]
253			srcReqByTicket[r.TicketID] = r
254		}
255		for _, t := range tickets {
256			r := srcReqByTicket[t.ID]
257			if r == nil {
258				return nil, fmt.Errorf("数据内部错误：源工单 %s 缺少报修请求绑定", t.ID)
259			}
260			if s.findRequest(r.RequestID) != nil {
261				return nil, fmt.Errorf(
262					"%w: 所选工单的请求标识 %q 已在目标台账绑定，整批拒绝导入", errConflict, r.RequestID)
263			}
264		}
265		// 所选资产的全部履历，按源履历序号升序，在目标最大序号之后依次分配。
266		events := make([]Event, 0)
267		for _, e := range src.data.Events {
268			if selected[e.AssetID] {
269				events = append(events, e)
270			}
271		}
272		sort.SliceStable(events, func(i, j int) bool { return events[i].Seq < events[j].Seq })
273		maxSeq := 0
274		for _, e := range s.data.Events {
275			if e.Seq > maxSeq {
276				maxSeq = e.Seq
277			}
278		}
279		// 履历序号容量：与 nextEventSeq 同一约束，可分配的最大序号为 math.MaxInt。
280		if len(events) > math.MaxInt-maxSeq {
281			return nil, fmt.Errorf(
282				"%w: 目标履历序号容量不足：当前最大序号 %d 无法容纳 %d 条导入履历，整批拒绝导入",
283				errConflict, maxSeq, len(events))
284		}
285		// 所选工单的全部备件领用记录，按源领用履历的全库序号整体排序（领用编号
286		// 只定位记录，编号大小不代表领用先后），再按此顺序重新分配领用编号。
287		srcTicketIDs := map[string]bool{}
288		for _, t := range tickets {
289			srcTicketIDs[t.ID] = true
290		}
291		srcWithdrawSeq := map[string]int{}
292		for _, e := range src.data.Events {
293			if e.Kind == eventPartWithdraw {
294				srcWithdrawSeq[e.WithdrawalID] = e.Seq
295			}
296		}
297		parts := make([]*PartWithdrawal, 0)
298		for _, p := range src.data.Parts {
299			if srcTicketIDs[p.TicketID] {
300				parts = append(parts, p)
301			}
302		}
303		sort.SliceStable(parts, func(i, j int) bool {
304			return srcWithdrawSeq[parts[i].ID] < srcWithdrawSeq[parts[j].ID]
305		})
306		// 领用编号容量：与 withdrawPart 同一约束，可分配的最大序号为 math.MaxInt-1。
307		if len(parts) > math.MaxInt-s.data.NextPartSeq {
308			return nil, fmt.Errorf(
309				"%w: 目标领用编号容量不足：下一序号 %d 无法容纳 %d 笔导入领用，整批拒绝导入",
310				errConflict, s.data.NextPartSeq, len(parts))
311		}
312		// 所选工单的全部附件索引（有效与已撤销都复制），按源登记履历的全库序号
313		// 整体排序（附件编号只定位记录，编号大小不代表登记先后），再按此顺序重新
314		// 分配附件编号。只复制索引记录与履历，不复制资料文件；文件当前不可用不使
315		// 导入失败。
316		srcAttachRegSeq := map[string]int{}
317		for _, e := range src.data.Events {
318			if e.Kind == eventAttach {
319				srcAttachRegSeq[e.AttachmentID] = e.Seq
320			}
321		}
322		attachments := make([]*Attachment, 0)
323		for _, a := range src.data.Attachments {
324			if srcTicketIDs[a.TicketID] {
325				attachments = append(attachments, a)
326			}
327		}
328		sort.SliceStable(attachments, func(i, j int) bool {
329			return srcAttachRegSeq[attachments[i].ID] < srcAttachRegSeq[attachments[j].ID]
330		})
331		// 附件编号容量：与 attach 同一约束，可分配的最大序号为 math.MaxInt-1。
332		if len(attachments) > math.MaxInt-s.data.NextAttachSeq {
333			return nil, fmt.Errorf(
334				"%w: 目标附件编号容量不足：下一序号 %d 无法容纳 %d 条导入附件索引，整批拒绝导入",
335				errConflict, s.data.NextAttachSeq, len(attachments))
336		}
337	
338		// 检查全部通过，一次性应用合并。资产编号、名称、位置、状态与工单的描述、
339		// 终态内容、负责人等业务信息原样保留；履历时间保留原瞬间与小数秒精度。
340		for _, a := range assets {
341			na := *a
342			s.data.Assets = append(s.data.Assets, &na)
343		}
344		// 所选资产的保养计划原样复制（内容、首次到期日、间隔与下一到期日不变）；
345		// 保养履历已随上方资产履历筛选一并复制，完成链自然接续。目标已有计划不变。
346		planCount := 0
347		for _, p := range src.data.Plans {
348			if selected[p.AssetID] {
349				np := *p
350				s.data.Plans = append(s.data.Plans, &np)
351				planCount++
352			}
353		}
354		outcome := &importOutcome{assetIDs: ids, plans: planCount}
355		remap := map[string]string{}
356		next := s.data.NextTicketSeq
357		for _, t := range tickets {
358			nt := *t
359			nt.ID = fmt.Sprintf("T%04d", next)
360			remap[t.ID] = nt.ID
361			s.data.Tickets = append(s.data.Tickets, &nt)
362			r := srcReqByTicket[t.ID]
363			s.data.Requests = append(s.data.Requests, requestBinding{
364				RequestID:   r.RequestID,
365				AssetID:     r.AssetID,
366				Description: r.Description,
367				TicketID:    nt.ID,
368			})
369			outcome.tickets = append(outcome.tickets, ticketRemap{OldID: t.ID, NewID: nt.ID})
370			next++
371		}
372		s.data.NextTicketSeq = next
373		// 备件领用记录按源领用顺序重新分配领用编号，工单引用同步替换；
374		// 数量、累计退回与说明等业务信息原样保留。
375		partIDs := map[string]string{}
376		nextPart := s.data.NextPartSeq
377		for _, p := range parts {
378			np := *p
379			np.ID = fmt.Sprintf("P%04d", nextPart)
380			np.TicketID = remap[p.TicketID]
381			partIDs[p.ID] = np.ID
382			s.data.Parts = append(s.data.Parts, &np)
383			outcome.parts = append(outcome.parts, partRemap{OldID: p.ID, NewID: np.ID})
384			nextPart++
385		}
386		s.data.NextPartSeq = nextPart
387		// 附件索引按源登记顺序重新分配附件编号，工单引用同步替换；
388		// 路径、撤销状态、说明与撤销理由等业务信息原样保留。
389		attachIDs := map[string]string{}
390		nextAttach := s.data.NextAttachSeq
391		for _, a := range attachments {
392			na := *a
393			na.ID = fmt.Sprintf("A%04d", nextAttach)
394			na.TicketID = remap[a.TicketID]
395			attachIDs[a.ID] = na.ID
396			s.data.Attachments = append(s.data.Attachments, &na)
397			outcome.attachments = append(outcome.attachments, attachRemap{OldID: a.ID, NewID: na.ID})
398			nextAttach++
399		}
400		s.data.NextAttachSeq = nextAttach
401		seq := maxSeq
402		seqRemap := map[int]int{}
403		for _, e := range events {
404			seq++
405			ne := e
406			ne.Seq = seq
407			ne.TicketID = remap[e.TicketID]
408			ne.WithdrawalID = partIDs[e.WithdrawalID]
409			ne.AttachmentID = attachIDs[e.AttachmentID]
410			if e.Kind == eventPlanRevoke || e.Kind == eventAccept {
411				// 撤销履历的目标完成序号、验收履历的目标提交序号随履历重编号同步
412				// 替换：目标在源序号顺序中先于撤销/验收出现（源台账已通过一致性
413				// 检查），此处必然已有映射。
414				ne.TargetSeq = seqRemap[e.TargetSeq]
415			}
416			seqRemap[e.Seq] = seq
417			if e.Kind == eventPlanDone {
418				outcome.completions = append(outcome.completions, completionRemap{OldSeq: e.Seq, NewSeq: seq})
419			}
420			if e.Kind == eventSubmit {
421				outcome.submissions = append(outcome.submissions, completionRemap{OldSeq: e.Seq, NewSeq: seq})
422			}
423			s.data.Events = append(s.data.Events, ne)
424		}
425		return outcome, nil
426	}
