13	// 提交-验收通过全流程：提交后工单待验收、资产仍维修中；验收通过后工单按该次
14	// 提交的维修结果关闭，资产恢复可用；履历含提交、验收与关闭三条记录。
15	func TestSubmitApproveLifecycle(t *testing.T) {
16		s := newTestStore(t)
17		if _, err := s.registerAsset("EQ-1", "打印机", "一楼"); err != nil {
18			t.Fatal(err)
19		}
20		tk, _, err := s.report("EQ-1", "卡纸", "req-1")
21		if err != nil {
22			t.Fatal(err)
23		}
24	
25		// 提交维修结果：工单转为待验收，返回提交履历的全库序号。
26		tk, submitSeq, err := s.submitRepair(tk.ID, "已更换搓纸轮")
27		if err != nil {
28			t.Fatalf("submitRepair: %v", err)
29		}
30		if tk.Status != ticketPending {
31			t.Fatalf("提交后工单状态 = %q，想得到 %q", tk.Status, ticketPending)
32		}
