37			t.Fatalf("待验收时资产应仍为维修中，得到 %q", got)
38		}
39		seq, result, ok := s.currentSubmission(tk.ID)
40		if !ok || seq != submitSeq || result != "已更换搓纸轮" {
41			t.Fatalf("当前待验收提交 = (%d, %q, %v)", seq, result, ok)
42		}
43	
44		// 验收通过：工单按提交的维修结果关闭，资产恢复可用。
45		tk, asset, err := s.acceptSubmission(tk.ID, submitSeq, decisionApprove, "复核通过")
46		if err != nil {
47			t.Fatalf("acceptSubmission: %v", err)
48		}
49		if tk.Status != ticketClosed || tk.Result != "已更换搓纸轮" || tk.ClosedAt == "" {
50			t.Fatalf("验收通过后工单异常: %+v", tk)
51		}
52		if asset.Status != statusAvailable {
53			t.Fatalf("验收通过后资产状态 = %q", asset.Status)
54		}
55	
56		// 履历：提交、验收（含决定、意见与目标序号）、关闭（内容为提交结果）。
57		events := s.eventsOf("EQ-1")
58		if len(events) != 4 {
59			t.Fatalf("履历条数 = %d，想得到 4", len(events))
60		}
61		if events[1].Kind != eventSubmit || events[1].Content != "已更换搓纸轮" || events[1].Seq != submitSeq {
62			t.Fatalf("提交履历不对: %+v", events[1])
63		}
64		if events[2].Kind != eventAccept || events[2].Decision != decisionApprove ||
65			events[2].Content != "复核通过" || events[2].TargetSeq != submitSeq {
66			t.Fatalf("验收履历不对: %+v", events[2])
67		}
68		if events[3].Kind != eventClose || events[3].Content != "已更换搓纸轮" {
69			t.Fatalf("关闭履历不对: %+v", events[3])
70		}
71	
72		// 终结后拒绝提交与验收。
73		if _, _, err := s.submitRepair(tk.ID, "再次提交"); !errors.Is(err, errConflict) {
74			t.Fatalf("已关闭工单提交应失败，得到 %v", err)
75		}
76		if _, _, err := s.acceptSubmission(tk.ID, submitSeq, decisionApprove, "再次验收"); !errors.Is(err, errConflict) {
77			t.Fatalf("已关闭工单验收应失败，得到 %v", err)
78		}
79	
80		// 重载后状态、结果与履历保持；旧请求重放返回已关闭工单。
81		s = saveAndReopen(t, s)
82		tk = s.findTicket("T0001")
83		if tk.Status != ticketClosed || tk.Result != "已更换搓纸轮" {
84			t.Fatalf("重载后工单状态未保持: %+v", tk)
85		}
86		old, replay, err := s.report("EQ-1", "卡纸", "req-1")
87		if err != nil || !replay || old.Status != ticketClosed {
88			t.Fatalf("重载后旧请求重放应返回已关闭工单: %v replay=%v err=%v", old, replay, err)
89		}
90		if got := len(s.eventsOf("EQ-1")); got != 4 {
91			t.Fatalf("重载后履历条数 = %d", got)
92		}
93	
94		// 停机区间：等待验收的时间计入原报修至关闭的停机区间。
95		var reportTime, closeTime int64
96		for _, e := range s.data.Events {
97			switch e.Kind {
98			case eventReport:
99				reportTime = e.Time.Unix()
100			case eventClose:
101				closeTime = e.Time.Unix()
102			}
103		}
104		res, err := s.downtimeForAssets([]string{"EQ-1"},
105			time.Unix(reportTime-10, 0), time.Unix(closeTime+10, 0))
106		if err != nil {
107			t.Fatal(err)
108		}
109		if res[0].Seconds != closeTime-reportTime {
110			t.Fatalf("停机秒数 = %d，想得到 %d", res[0].Seconds, closeTime-reportTime)
111		}
112	}
