114	// 返修重提：验收退回后工单恢复未关闭、资产仍维修中，不能绕过验收直接关闭；
115	// 再次提交产生新序号，验收通过后按新提交结果关闭；旧提交与意见全部保留。
116	func TestSubmitRejectAndResubmit(t *testing.T) {
117		s := newTestStore(t)
