126		if _, _, err := s.submitRepair(tk.ID, "重复提交"); !errors.Is(err, errConflict) {
127			t.Fatalf("待验收时重复提交应失败，得到 %v", err)
128		}
129		// 验收退回：恢复未关闭，资产仍维修中，不填写维修结果。
130		tk, asset, err := s.acceptSubmission(tk.ID, seq1, decisionReject, "仍有卡纸，需返修")
131		if err != nil {
132			t.Fatalf("验收退回: %v", err)
133		}
134		if tk.Status != ticketOpen || tk.Result != "" {
135			t.Fatalf("退回后工单异常: %+v", tk)
136		}
137		if asset.Status != statusRepairing {
138			t.Fatalf("退回后资产应仍为维修中，得到 %q", asset.Status)
139		}
140		// 退回后不能绕过验收直接关闭。
141		if _, _, err := s.closeTicket(tk.ID, "直接关闭"); !errors.Is(err, errConflict) {
142			t.Fatalf("首次提交后直接关闭应失败，得到 %v", err)
143		}
144		// 再次提交产生新序号。
145		tk, seq2, err := s.submitRepair(tk.ID, "已更换搓纸轮")
146		if err != nil {
147			t.Fatal(err)
148		}
149		if seq2 <= seq1 {
150			t.Fatalf("再次提交序号 %d 应大于首次 %d", seq2, seq1)
151		}
152		// 第二次验收通过：按第二次提交内容关闭。
153		tk, _, err = s.acceptSubmission(tk.ID, seq2, decisionApprove, "复核通过")
154		if err != nil {
155			t.Fatal(err)
156		}
157		if tk.Result != "已更换搓纸轮" {
158			t.Fatalf("维修结果应取第二次提交内容，得到 %q", tk.Result)
159		}
160	
161		// 旧提交与验收意见全部保留：提交×2、验收×2、关闭×1。
162		var submits, accepts, closes int
163		for _, e := range s.eventsOf("EQ-1") {
164			switch e.Kind {
165			case eventSubmit:
166				submits++
167			case eventAccept:
168				accepts++
169				if e.TargetSeq == seq1 && (e.Decision != decisionReject || e.Content != "仍有卡纸，需返修") {
170					t.Fatalf("首次验收履历未保留: %+v", e)
171				}
172			case eventClose:
173				closes++
174			}
175		}
176		if submits != 2 || accepts != 2 || closes != 1 {
177			t.Fatalf("履历统计 = 提交%d/验收%d/关闭%d，想得到 2/2/1", submits, accepts, closes)
178		}
179		s = saveAndReopen(t, s)
180		if got := s.findTicket("T0001"); got.Status != ticketClosed || got.Result != "已更换搓纸轮" {
181			t.Fatalf("重载后工单异常: %+v", got)
182		}
183	}
