407	// 矛盾台账：提交/验收链的归属、转换、引用与保存值矛盾时全部读写拒绝且不修复。
408	func TestContradictorySubmissionLedgers(t *testing.T) {
409		submitEvent := func(seq int, ticketID, result string) map[string]any {
410			return map[string]any{
411				"seq": seq, "asset_id": "EQ-1", "ticket_id": ticketID,
412				"kind": "提交", "content": result, "time": "2026-10-01T10:30:00Z",
413			}
414		}
415		acceptEvent := func(seq int, ticketID string, target int, decision string) map[string]any {
416			return map[string]any{
417				"seq": seq, "asset_id": "EQ-1", "ticket_id": ticketID,
418				"kind": "验收", "content": "意见", "decision": decision,
419				"target_seq": target, "time": "2026-10-01T11:00:00Z",
420			}
421		}
422		pendingTicket := func(m map[string]any) {
423			m["tickets"].([]any)[0].(map[string]any)["status"] = "待验收"
424			appendTo(m, "events", submitEvent(4, "T0001", "已更换搓纸轮"))
425		}
426		cases := []struct {
427			name    string
428			mutate  func(m map[string]any)
429			wantErr string
430		}{
431			{"保存待验收但无提交履历", func(m map[string]any) {
432				m["tickets"].([]any)[0].(map[string]any)["status"] = "待验收"
433			}, "状态矛盾"},
434			{"有提交履历但保存未关闭", func(m map[string]any) {
435				appendTo(m, "events", submitEvent(4, "T0001", "已更换搓纸轮"))
436			}, "状态矛盾"},
437			{"验收目标不是当前提交", func(m map[string]any) {
438				pendingTicket(m)
439				appendTo(m, "events", acceptEvent(5, "T0001", 99, "通过"))
440			}, "履历矛盾"},
441			{"验收决定无效", func(m map[string]any) {
442				pendingTicket(m)
443				appendTo(m, "events", acceptEvent(5, "T0001", 4, "待定"))
444			}, "履历矛盾"},
445			{"提交退回后直接关闭", func(m map[string]any) {
446				tk := m["tickets"].([]any)[0].(map[string]any)
447				tk["status"] = "已关闭"
448				tk["result"] = "直接关闭"
449				tk["closed_at"] = "2026-10-01T11:00:00Z"
450				m["assets"].([]any)[0].(map[string]any)["status"] = "可用"
451				appendTo(m, "events", submitEvent(4, "T0001", "已更换搓纸轮"))
452				appendTo(m, "events", acceptEvent(5, "T0001", 4, "退回"))
453				appendTo(m, "events", eventJSONMap(6, "T0001", "关闭", "直接关闭"))
454			}, "履历矛盾"},
455			{"验收通过但缺关闭履历", func(m map[string]any) {
456				pendingTicket(m)
457				appendTo(m, "events", acceptEvent(5, "T0001", 4, "通过"))
458			}, "状态矛盾"},
459			{"跨单验收引用", func(m map[string]any) {
460				pendingTicket(m)
461				m["assets"] = append(m["assets"].([]any), map[string]any{
462					"id": "EQ-2", "name": "空调", "location": "二楼", "status": "维修中",
463				})
464				m["tickets"] = append(m["tickets"].([]any), map[string]any{
465					"id": "T0002", "asset_id": "EQ-2", "description": "不制冷",
466					"request_id": "req-2", "status": "待验收", "created_at": "2026-10-01T09:30:00Z",
467				})
468				m["requests"] = append(m["requests"].([]any), map[string]any{
469					"request_id": "req-2", "asset_id": "EQ-2", "description": "不制冷", "ticket_id": "T0002",
470				})
471				appendTo(m, "events", map[string]any{
472					"seq": 5, "asset_id": "EQ-2", "ticket_id": "T0002",
473					"kind": "报修", "content": "不制冷", "time": "2026-10-01T09:30:00Z",
474				})
475				appendTo(m, "events", map[string]any{
476					"seq": 6, "asset_id": "EQ-2", "ticket_id": "T0002",
477					"kind": "提交", "content": "已加氟", "time": "2026-10-01T10:00:00Z",
478				})
479				// T0001 的验收指向 T0002 的提交序号。
480				appendTo(m, "events", acceptEvent(7, "T0001", 6, "通过"))
481			}, "履历矛盾"},
482		}
483		for _, tc := range cases {
484			t.Run(tc.name, func(t *testing.T) {
485				dir := t.TempDir()
486				raw := writeLedger(t, dir, tc.mutate)
487				if _, err := openStore(dir); err == nil || !strings.Contains(err.Error(), tc.wantErr) {
488					t.Fatalf("矛盾台账应拒绝（%s），得到 %v", tc.wantErr, err)
489				}
490				var out, errBuf bytes.Buffer
491				if code := run([]string{"list", "--data-dir", dir}, &out, &errBuf); code != 1 {
492					t.Fatalf("查询应退出 1，得到 %d（%s）", code, errBuf.String())
493				}
494				if code := run([]string{"submit", "--data-dir", dir, "--ticket-id", "T0001",
495					"--repair-result", "x"}, &out, &errBuf); code != 1 {
496					t.Fatalf("写入应退出 1，得到 %d（%s）", code, errBuf.String())
497				}
498				got, err := os.ReadFile(filepath.Join(dir, dataFileName))
499				if err != nil || !bytes.Equal(got, raw) {
500					t.Fatal("矛盾台账原文件字节应保持不变")
501				}
502			})
503		}
504	}
