5	// 维修提交验收链规则核心：提交、验收、直接关闭与取消的业务判定、提交身份与
6	// 工单状态推导全部收敛于此。
7	//
8	// 日常操作（submit/accept/close/cancel）以候选履历先走一遍核心判定，通过后
9	// 才分配序号、修改业务记录；台账加载与保存前校验按全库履历序号重放同一核心；
10	// ticket 的当前待验收提交查询与 replay 截止回看同样只依据核心推出的状态。
11	// 各路径不再分别维护“是否提交过/当前提交是谁/工单处于何态”的重复判定。
12	//
13	// 核心按全库履历序号逐步采纳履历，每一步都以当时的工单状态做判定：
14	//   - 报修使工单进入未关闭；
15	//   - 提交仅在未关闭时接受非空维修结果，工单转为待验收，提交履历的全库序号
16	//     即该次提交身份；
17	//   - 验收仅在待验收时接受，且目标序号必须恰为当前待验收提交，未知序号、非
18	//     提交序号、跨单提交、已处理或过时目标一律拒绝；通过进入“验收通过待关闭”
19	//     中间态（内容锁定为该次提交结果），紧随的同单关闭履历内容匹配才终结，
20	//     退回则恢复未关闭，可再次提交并产生新身份；
21	//   - 关闭在未关闭且从未提交时直接接受，在待关闭中间态只接受内容匹配的关闭，
22	//     其余状态拒绝；
23	//   - 取消在未关闭或待验收时接受，清除当前待验收提交，保留全部提交历史。
24	//
25	// “验收通过待关闭”只存在于同次保存的验收履历与关闭履历之间，绝不会作为
26	// 保存状态出现：截止回看纳入验收、尚未纳入关闭时，工单仍未终结、资产仍维修
27	// 中，但当前待验收提交为无。
28	//
29	// 核心只推进自己的派生状态，从不修改传入的履历、工单或资产等业务记录，也不
30	// 借校验补字段或修复数据；判定失败时派生状态保持判定前原样。
31	
32	// repairRuleCode 为维修链规则冲突的类别，供各场景包装成各自的错误信息。
33	type repairRuleCode int
34	
35	const (
36		ruleRepairDuplicateReport   repairRuleCode = iota // 同一工单多条报修履历
37		ruleRepairNoReport                                // 终结/提交类履历出现在报修履历之前
38		ruleSubmitNotOpen                                 // 提交时工单不是未关闭
39		ruleSubmitEmptyResult                             // 提交维修结果为空
40		ruleCloseNoReport                                 // 关闭履历出现在报修履历之前
41		ruleCloseAlreadyClosed                            // 已关闭工单重复关闭
42		ruleCloseAlreadyCancelled                         // 已取消工单被关闭
43		ruleClosePending                                  // 待验收工单被直接关闭
44		ruleCloseAfterSubmit                              // 首次提交后直接关闭
45		ruleCloseApprovedMismatch                         // 待关闭中间态的关闭内容与验收提交结果不一致
46		ruleCloseEmptyResult                              // 关闭维修结果为空
47		ruleCancelNoReport                                // 取消履历出现在报修履历之前
48		ruleCancelAlreadyClosed                           // 已关闭工单被取消
49		ruleCancelAlreadyCancelled                        // 已取消工单重复取消
50		ruleCancelApprovedPending                         // 验收通过待关闭中间态出现取消履历
51		ruleAcceptNotPending                              // 验收时工单不是待验收
52		ruleAcceptEmptyComment                            // 验收意见为空
53		ruleAcceptBadDecision                             // 验收决定既不是通过也不是退回
54		ruleAcceptTargetUnknown                           // 验收目标序号不存在
55		ruleAcceptTargetNotSubmit                         // 验收目标序号不是提交履历
56		ruleAcceptTargetCrossTicket                       // 验收目标属于其他工单
57		ruleAcceptTargetProcessed                         // 验收目标已处理或不是当前提交
58	)
59	
60	// repairRuleError 为核心判定返回的规则冲突，携带各场景包装错误所需的上下文。
61	type repairRuleError struct {
62		code     repairRuleCode
63		ticketID string
64		seq      int    // 触发判定的履历序号
65		target   int    // 验收目标提交序号
66		from     string // 判定前的工单状态
67		kind     string // 目标序号实际的履历类型（ruleAcceptTargetNotSubmit）
68		owner    string // 目标序号实际归属的工单（ruleAcceptTargetCrossTicket）
69		contentA string // 关闭内容 / 验收锁定的提交结果
70		contentB string // 对照的提交结果
71	}
72	
73	func (e *repairRuleError) Error() string {
74		return fmt.Sprintf("维修链规则冲突 %d（工单 %s，履历序号 %d）", int(e.code), e.ticketID, e.seq)
75	}
76	
77	// ticketRepair 为单张工单的提交验收链派生状态。
78	type ticketRepair struct {
79		status         string // 空串：尚未报修；否则为未关闭/待验收/验收通过待关闭/已关闭/已取消
80		submittedEver  bool   // 是否曾提交（含已退回的提交）
81		pendingSeq     int    // 当前待验收提交的全库履历序号
82		pendingResult  string // 当前待验收提交的维修结果
83		approvedResult string // 验收通过待关闭时锁定的提交维修结果
84	}
85	
86	// repairCore 为全部工单的维修链派生状态重放器。eventBySeq 收录已采纳履历中
87	// 每个全库序号对应的履历，用于验收目标的身份分类。
88	type repairCore struct {
89		tickets    map[string]*ticketRepair
90		eventBySeq map[int]Event
91	}
92	
93	func newRepairCore() *repairCore {
94		return &repairCore{tickets: map[string]*ticketRepair{}, eventBySeq: map[int]Event{}}
95	}
96	
97	// state 返回工单的派生状态；尚无报修履历的工单返回空状态（不代表业务工单存在）。
98	func (c *repairCore) state(ticketID string) *ticketRepair {
99		st := c.tickets[ticketID]
100		if st == nil {
101			st = &ticketRepair{}
102			c.tickets[ticketID] = st
103		}
104		return st
105	}
106	
107	// status 返回工单由履历链推出的状态；从未报修时为空串。注意“验收通过待关闭”
108	// 中间态也由此返回，调用方不得把它当作可保存状态。
109	func (c *repairCore) status(ticketID string) string {
110		st := c.tickets[ticketID]
111		if st == nil {
112			return ""
113		}
114		return st.status
115	}
116	
117	// submittedEver 报告工单是否曾提交过维修（含已退回的提交）。
118	func (c *repairCore) submittedEver(ticketID string) bool {
119		st := c.tickets[ticketID]
120		return st != nil && st.submittedEver
121	}
122	
123	// pending 返回工单当前待验收提交的全库履历序号与维修结果；无待验收提交（未
124	// 提交、已退回、待关闭中间态、已终结）时 ok=false。
125	func (c *repairCore) pending(ticketID string) (seq int, result string, ok bool) {
126		st := c.tickets[ticketID]
127		if st == nil || st.status != ticketPending {
128			return 0, "", false
129		}
130		return st.pendingSeq, st.pendingResult, true
131	}
132	
133	// apply 按全库履历序号顺序采纳一条履历：维修链履历按当时状态判定并推进派生
134	// 状态，其余履历忽略。判定失败返回 *repairRuleError，派生状态（含序号索引）
135	// 保持判定前原样。传入的履历不被修改。候选履历（日常操作预判）可使用零序号；
136	// 此时它不会进入 eventBySeq 索引，也不影响其他工单的判定。
137	func (c *repairCore) apply(e Event) error {
138		var err error
139		switch e.Kind {
140		case eventReport:
141			err = c.applyReport(e)
142		case eventSubmit:
143			err = c.applySubmit(e)
144		case eventAccept:
145			err = c.applyAccept(e)
146		case eventClose:
147			err = c.applyClose(e)
148		case eventCancel:
149			err = c.applyCancel(e)
150		}
151		// 仅在判定通过后才收录序号索引，保证失败不留下任何派生痕迹。
152		if err == nil && e.Seq > 0 {
153			c.eventBySeq[e.Seq] = e
154		}
155		return err
156	}
157	
158	// applyReport 判定并采纳报修履历：每张工单恰有一条，报修后工单未关闭。
159	func (c *repairCore) applyReport(e Event) error {
160		st := c.state(e.TicketID)
161		if st.status != "" {
162			return &repairRuleError{code: ruleRepairDuplicateReport, ticketID: e.TicketID, seq: e.Seq}
163		}
164		st.status = ticketOpen
165		return nil
166	}
167	
168	// applySubmit 判定并采纳提交履历：仅未关闭工单可提交非空维修结果，提交后工单
169	// 转为待验收，履历全库序号即该次提交身份。
170	func (c *repairCore) applySubmit(e Event) error {
171		st := c.state(e.TicketID)
172		if e.Content == "" {
173			return &repairRuleError{code: ruleSubmitEmptyResult, ticketID: e.TicketID, seq: e.Seq}
174		}
175		if st.status != ticketOpen {
176			return &repairRuleError{code: ruleSubmitNotOpen, ticketID: e.TicketID, seq: e.Seq, from: st.status}
177		}
178		st.status = ticketPending
179		st.pendingSeq = e.Seq
180		st.pendingResult = e.Content
181		st.submittedEver = true
182		return nil
183	}
184	
185	// classifyTarget 核对验收目标序号是否恰为工单当前待验收提交，返回不匹配的
186	// 规则类别与上下文：未知序号、非提交序号、跨单提交、已处理或非当前提交。
187	func (c *repairCore) classifyTarget(e Event, st *ticketRepair) repairRuleCode {
188		target, ok := c.eventBySeq[e.TargetSeq]
189		if !ok {
190			return ruleAcceptTargetUnknown
191		}
192		if target.Kind != eventSubmit {
193			return ruleAcceptTargetNotSubmit
194		}
195		if target.TicketID != e.TicketID {
196			return ruleAcceptTargetCrossTicket
197		}
198		if target.Seq != st.pendingSeq {
199			return ruleAcceptTargetProcessed
200		}
201		return -1
202	}
203	
204	// applyAccept 判定并采纳验收履历：仅待验收工单可验收，意见非空、决定合法，
205	// 目标序号须恰为当前待验收提交。通过进入待关闭中间态并锁定提交结果；退回
206	// 恢复未关闭并清除当前提交，可再次提交产生新身份。
207	func (c *repairCore) applyAccept(e Event) error {
208		st := c.state(e.TicketID)
209		if e.Decision != decisionApprove && e.Decision != decisionReject {
210			return &repairRuleError{code: ruleAcceptBadDecision, ticketID: e.TicketID, seq: e.Seq}
211		}
212		if e.Content == "" {
213			return &repairRuleError{code: ruleAcceptEmptyComment, ticketID: e.TicketID, seq: e.Seq}
214		}
215		if st.status != ticketPending {
216			return &repairRuleError{code: ruleAcceptNotPending, ticketID: e.TicketID, seq: e.Seq, from: st.status}
217		}
218		if code := c.classifyTarget(e, st); code >= 0 {
219			re := &repairRuleError{code: code, ticketID: e.TicketID, seq: e.Seq, target: e.TargetSeq}
220			if ev, ok := c.eventBySeq[e.TargetSeq]; ok {
221				re.kind = ev.Kind
222				re.owner = ev.TicketID
223			}
224			return re
225		}
226		if e.Decision == decisionApprove {
227			st.status = derivedApproved
228			st.approvedResult = st.pendingResult
229		} else {
230			st.status = ticketOpen
231		}
232		st.pendingSeq = 0
233		st.pendingResult = ""
234		return nil
235	}
236	
237	// applyClose 判定并采纳关闭履历：未关闭且从未提交的工单可直接关闭；待关闭

