14	// 返修重提的核心状态推导：提交→待验收，退回→未关闭且当前提交清空，再次提交
15	// 产生新身份；每个关键节点的状态、当前待验收提交与“曾提交”标记都以共用核心
16	// 为准，而不是各路径各自维护的判定。
17	func TestRepairCoreRejectResubmitState(t *testing.T) {
18		s := newTestStore(t)
19		_, _ = s.registerAsset("EQ-1", "打印机", "一楼")
20		tk, _, _ := s.report("EQ-1", "卡纸", "req-1")
