42			t.Fatalf("待验收当前提交 = (%d,%q,%v)", got, r, ok)
43		}
44		// 退回：恢复未关闭，当前待验收提交清空，但曾提交标记保留。
45		if _, _, err := s.acceptSubmission(tk.ID, seq1, decisionReject, "需返修"); err != nil {
