70	// 直接以履历驱动共用核心，覆盖验收目标的四类拒绝（未知、非提交、跨单、已处理）
71	// 以及提交/关闭/取消在错误状态下的拒绝；一次判定失败不得改变派生状态，随后
72	// 正确的履历仍应被采纳。
73	func TestRepairCoreTargetClassificationAndGuards(t *testing.T) {
74		// 构造两张工单：T1 提交(2)→退回(3)→提交(4)；T2 报修(5)→提交(6)。
75		ev := func(seq int, ticket, kind, content, decision string, target int) Event {
76			return Event{Seq: seq, AssetID: "EQ-1", TicketID: ticket, Kind: kind,
77				Content: content, Decision: decision, TargetSeq: target,
78				Time: time.Unix(int64(seq), 0)}
79		}
80		history := []Event{
81			ev(1, "T1", eventReport, "卡纸", "", 0),
82			ev(2, "T1", eventSubmit, "第一次", "", 0),
83			ev(3, "T1", eventAccept, "退回", decisionReject, 2),
84			ev(4, "T1", eventSubmit, "第二次", "", 0),
85			ev(5, "T2", eventReport, "不制冷", "", 0),
86			ev(6, "T2", eventSubmit, "他单结果", "", 0),
87		}
88		replay := func(upto int) *repairCore {
